#!/usr/bin/env python3
"""Extract readable dialogue from Claude Code or Codex session JSONL.
Usage: extract.py FILE [--max-chars N]
Prints: timestamp role: text (tool calls compressed to one line)."""
import json, sys

path = sys.argv[1]
maxc = 1500
if "--max-chars" in sys.argv:
    maxc = int(sys.argv[sys.argv.index("--max-chars") + 1])

def clip(s, n=None):
    n = n or maxc
    s = " ".join(s.split())
    return s if len(s) <= n else s[:n] + " …[cut]"

for line in open(path, errors="replace"):
    line = line.strip()
    if not line:
        continue
    try:
        j = json.loads(line)
    except Exception:
        continue
    ts = (j.get("timestamp") or "")[:16]
    t = j.get("type")
    # Claude Code format
    if t in ("user", "assistant"):
        m = j.get("message") or {}
        c = m.get("content")
        if isinstance(c, str):
            print(f"{ts} {t}: {clip(c)}")
            continue
        for b in c or []:
            bt = b.get("type")
            if bt == "text":
                print(f"{ts} {t}: {clip(b.get('text',''))}")
            elif bt == "tool_use":
                name = b.get("name","?")
                inp = json.dumps(b.get("input",{}), ensure_ascii=False)
                print(f"{ts} {t} TOOL {name}: {clip(inp, 300)}")
            elif bt == "tool_result":
                cc = b.get("content")
                if isinstance(cc, list):
                    cc = " ".join(x.get("text","") for x in cc if isinstance(x,dict))
                print(f"{ts} {t} RESULT: {clip(str(cc), 300)}")
    elif t == "summary":
        print(f"== SUMMARY: {clip(j.get('summary',''), 500)}")
    # Codex rollout format
    elif t == "response_item":
        p = j.get("payload") or {}
        pt = p.get("type")
        if pt == "message":
            role = p.get("role","?")
            txt = " ".join(x.get("text","") for x in p.get("content",[]) if isinstance(x,dict))
            if txt.strip():
                print(f"{ts} codex-{role}: {clip(txt)}")
        elif pt in ("function_call","local_shell_call"):
            print(f"{ts} codex TOOL {p.get('name','shell')}: {clip(str(p.get('arguments') or p.get('action') or ''), 300)}")
        elif pt == "function_call_output":
            print(f"{ts} codex RESULT: {clip(str(p.get('output','')), 300)}")
    elif t == "session_meta":
        p = j.get("payload") or {}
        print(f"== CODEX SESSION cwd={p.get('cwd')} instructions={clip(str(p.get('instructions'))[:400],400)}")

