import hashlib, os, re, collections
H=os.path.expanduser("~")
bodies={
 "product-prover":H+"/.claude/skills/product-prover/SKILL.md",
 "build-pipeline":H+"/live-spec/skills/build-pipeline/SKILL.md",
 "spec-author":H+"/live-spec/skills/spec-author/SKILL.md",
 "live-spec-base":H+"/live-spec/skills/live-spec-base/SKILL.md",
 "communicator":H+"/live-spec/skills/communicator/SKILL.md",
 "skill-creator":H+"/.claude/skills/skill-creator/SKILL.md",
 "text-audit":H+"/live-spec/skills/text-audit/SKILL.md",
}
seen=collections.defaultdict(list)
for name,p in bodies.items():
    txt=open(p).read()
    for para in re.split(r'\n\s*\n', txt):
        norm=" ".join(para.split())
        if len(norm)<120: continue
        h=hashlib.md5(norm.encode()).hexdigest()
        seen[h].append((name,len(norm)))
dup_bytes=collections.Counter(); dup_examples=[]
for h,occ in seen.items():
    names={o[0] for o in occ}
    if len(occ)>1:
        size=occ[0][1]
        for name,_ in occ[1:]:
            dup_bytes[name]+=size
        if len(dup_examples)<12: dup_examples.append((sorted(names), len(occ), size))
print("EXACT duplicate paragraph bytes charged to later copies, per skill:")
for k,v in dup_bytes.most_common(): print(f"  {k}: {v}")
print("examples (skills, count, size):")
for e in dup_examples: print(" ", e)
tot={n:os.path.getsize(p) for n,p in bodies.items()}
print("totals:", tot, "sum:", sum(tot.values()))
EOF

